<?php
require_once __DIR__.'/includes/functions.php'; exigir_tipo(['gerente','funcionario']); $titulo='Contas'; $erro='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $acao=$_POST['acao']??'';
 if($acao==='cadastrar'){
  $conta=trim($_POST['conta']??'');$senhaNova=$_POST['senha']??'';$agencia=trim($_POST['agencia']??'');$bancoNome=trim($_POST['banco']??'');$cliente=trim($_POST['cliente']??'');$cpf=trim($_POST['cpf']??'');$telefone=trim($_POST['telefone']??'');$endereco=trim($_POST['endereco']??'');$email=trim($_POST['email']??'');$data=$_POST['data_abertura']??date('Y-m-d');
  if($conta===''||$senhaNova===''||$cliente==='')$erro='Preencha número da conta, senha e nome do cliente.';
  elseif(strlen($conta)>10||strlen($agencia)>4||strlen($bancoNome)>30||strlen($cliente)>30||strlen($cpf)>14||strlen($telefone)>15||strlen($endereco)>40||strlen($email)>30)$erro='Um ou mais campos ultrapassam o tamanho permitido na apostila.';
  else {$hash=password_hash($senhaNova,PASSWORD_DEFAULT);$status='A';$stmt=mysqli_prepare($conexao,'INSERT INTO tbcontas (conta, senha, agencia, banco, cliente, cpf, telefone, endereco, email, data_abertura, data_encerramento, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, ?)');mysqli_stmt_bind_param($stmt,'sssssssssss',$conta,$hash,$agencia,$bancoNome,$cliente,$cpf,$telefone,$endereco,$email,$data,$status);if(mysqli_stmt_execute($stmt)){$_SESSION['mensagem']='Conta cadastrada com sucesso.';redirecionar('contas.php');}$erro='Não foi possível cadastrar. Verifique se o número da conta já existe e se os dados estão corretos.';mysqli_stmt_close($stmt);}
 } elseif($acao==='fechar'){$conta=trim($_POST['conta']??'');$data=date('Y-m-d');$status='F';$stmt=mysqli_prepare($conexao,"UPDATE tbcontas SET status=?, data_encerramento=? WHERE conta=? AND status='A'");mysqli_stmt_bind_param($stmt,'sss',$status,$data,$conta);mysqli_stmt_execute($stmt);$_SESSION['mensagem']='Operação de fechamento concluída.';redirecionar('contas.php');}
}
$filtro=trim($_GET['buscar']??'');if($filtro!==''){$like='%'.$filtro.'%';$stmt=mysqli_prepare($conexao,'SELECT conta, agencia, banco, cliente, cpf, data_abertura, status FROM tbcontas WHERE conta LIKE ? OR cliente LIKE ? ORDER BY cliente');mysqli_stmt_bind_param($stmt,'ss',$like,$like);mysqli_stmt_execute($stmt);$lista=mysqli_stmt_get_result($stmt);}else{$lista=mysqli_query($conexao,'SELECT conta, agencia, banco, cliente, cpf, data_abertura, status FROM tbcontas ORDER BY cliente');}
include __DIR__.'/includes/header.php'; ?>
<div class="cabecalho-pagina"><div><span class="etiqueta">CADASTRO BANCÁRIO</span><h1>Contas bancárias</h1><p>Cadastre clientes, consulte contas e realize o fechamento.</p></div></div><?php if($erro): ?><div class="alerta"><?=e($erro)?></div><?php endif; ?><section class="painel"><h2>Nova conta</h2><form method="post" autocomplete="off"><input type="hidden" name="acao" value="cadastrar"><div class="form-grade"><div><label>Número da conta *</label><input name="conta" maxlength="10" required></div><div><label>Senha da conta *</label><input name="senha" type="password" required></div><div><label>Agência</label><input name="agencia" maxlength="4"></div><div><label>Banco</label><input name="banco" maxlength="30" value="SO BANK"></div><div><label>Nome do cliente *</label><input name="cliente" maxlength="30" required></div><div><label>CPF</label><input name="cpf" maxlength="14"></div><div><label>Telefone</label><input name="telefone" maxlength="15"></div><div><label>E-mail</label><input name="email" type="email" maxlength="30"></div><div class="campo-largo"><label>Endereço</label><input name="endereco" maxlength="40"></div><div><label>Data de abertura</label><input name="data_abertura" type="date" value="<?=date('Y-m-d')?>"></div></div><button class="botao botao-principal" type="submit">Cadastrar conta</button></form></section><section class="painel margem-topo"><div class="secao-titulo"><div><h2>Contas cadastradas</h2><p>Contas ativas e encerradas.</p></div><form method="get" class="busca"><input name="buscar" value="<?=e($filtro)?>" placeholder="Conta ou cliente"><button class="botao">Pesquisar</button></form></div><div class="tabela-responsiva"><table><thead><tr><th>Conta</th><th>Cliente</th><th>Agência</th><th>CPF</th><th>Abertura</th><th>Status</th><th>Ação</th></tr></thead><tbody><?php if($lista): while($c=mysqli_fetch_assoc($lista)): ?><tr><td><?=e($c['conta'])?></td><td><?=e($c['cliente'])?></td><td><?=e($c['agencia'])?></td><td><?=e($c['cpf'])?></td><td><?=e($c['data_abertura'])?></td><td><span class="status <?= $c['status']==='A'?'status-ok':'status-off' ?>"><?= $c['status']==='A'?'Ativa':'Fechada' ?></span></td><td><?php if($c['status']==='A'): ?><form method="post" onsubmit="return confirm('Deseja fechar esta conta?')"><input type="hidden" name="acao" value="fechar"><input type="hidden" name="conta" value="<?=e($c['conta'])?>"><button class="botao botao-perigo">Fechar</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endwhile; endif; ?></tbody></table></div></section><?php include __DIR__.'/includes/footer.php'; ?>
